{"task": "Find all event paths that contain a semantic version string like v1.2.3", "sql": "SELECT path FROM events WHERE regexp_like(path, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Find all log messages that contain a semantic version string like v1.2.3", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Count how many events reference each distinct path-embedded version number", "sql": "SELECT regexp_match(path, 'v([0-9]+\\.[0-9]+\\.[0-9]+)')[1] AS version, COUNT(*) AS cnt FROM events WHERE regexp_like(path, 'v[0-9]+\\.[0-9]+\\.[0-9]+') GROUP BY version ORDER BY cnt DESC"}
{"task": "List error-level log messages that mention a version string, to investigate version-specific failures", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Flag events whose path contains an old major version (v0.x.x) for deprecation tracking", "sql": "SELECT id, user_id, path FROM events WHERE regexp_like(path, 'v0\\.[0-9]+\\.[0-9]+')"}
{"task": "Categorize log lines by whether they mention a version string using a CASE expression", "sql": "SELECT ts, service, CASE WHEN regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+') THEN 'has_version' ELSE 'no_version' END AS version_flag FROM logs"}
{"task": "Find events with non-2xx status whose path includes a version string, to spot failing versioned endpoints", "sql": "SELECT id, path, status FROM events WHERE status >= 400 AND regexp_like(path, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Case-insensitively search log messages for a version string following the word 'version'", "sql": "SELECT ts, message FROM logs WHERE regexp_like(message, 'version[: ]*v?[0-9]+\\.[0-9]+\\.[0-9]+', 'i')"}
{"task": "Identify distinct services that have logged a version string in their messages", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, 'v[0-9]+\\.[0-9]+\\.[0-9]+')"}
{"task": "Count events per path prefix that includes a versioned API segment like /api/v1.2.3/", "sql": "SELECT path, COUNT(*) AS cnt FROM events WHERE regexp_like(path, '/api/v[0-9]+\\.[0-9]+\\.[0-9]+/') GROUP BY path ORDER BY cnt DESC"}

